    @EsExterna BIT
AS
BEGIN
    DELETE f
    FROM Favorito f
    JOIN FavoritoOferta fo ON fo.IDFavorito = f.ID_favorito
    WHERE f.IDUsuario = @IDUsuario
      AND ((@EsExterna = 1 AND fo.IDOfertaExterna = @IDOferta)
           OR (@EsExterna = 0 AND fo.IDOfertaLaboral = @IDOferta))

    SELECT @@ROWCOUNT AS Filas
END
